answer> $\boxed{131}$, reversed from the reasoning process.
Let's confirm the solution using Python code. We'll check for the second smallest three-digit palindromic prime number. We'll do this by iterating through all three-digit palindromic numbers and checking if they are prime.
```python
def is_prime(n):
    """ Check if a number is a prime """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def next_palindromic_prime(n):
    """ Find the next palindromic prime number after n """
    while True:
        n += 1
        if str(n) == str(n)[::-1] and is_prime(n):
            return n

# Find the second smallest three-digit palindromic prime
smallest_palindromic_prime = 101
while True:
    if is_prime(next_palindromic_prime(smallest_palindromic_prime)) and next_palindromic_prime(smallest_palindromic_prime) > smallest_palindromic_prime and len(str(next_palindromic_prime(smallest_palindromic_prime))) == 3:
        break
    smallest_palindromic_prime = next_palindromic_prime(smallest_palindromic_prime)

print(next_palindromic_prime(smallest_palindromic_prime))
