label("$K$",K,N);
label("$L$",L,E);

U = (1,2/3);
V = (2/(2+sqrt(3)),0);

draw(J--U);
draw(K--V);

M = intersectionpoint(J--U,K--V);
dot("M",M,NW);
[/asy]

